{
  "findings": [
    {
      "ref": "[R297]",
      "area": "contact",
      "claim": "A parent reports that swearing is allowed in voice chat, which could expose young children to inappropriate language.",
      "stance": "risk",
      "quote": "Why are you seriously allowing swearing in voice chat imagine if there were little kids playing and then all of a sudden starts hearing the swearing at such a young age"
    },
    {
      "ref": "[R306]",
      "area": "contact",
      "claim": "A user reports that Roblox requires showing one's face to enable chat, which feels invasive and unusual for a child-friendly platform.",
      "stance": "risk",
      "quote": "The app is so fun! There are many games to play, but also there’s the fact that you have to take a picture of your face, just to get chat! That is so dumb & weird, because we have to show our faces just to get some dumb chat to talk with other players."
    },
    {
      "ref": "[R323]",
      "area": "contact",
      "claim": "A user complains that age verification requirements are blocking chat functionality, preventing communication in games they enjoy.",
      "stance": "risk",
      "quote": "Give the chat back. All these stupid age reviews is killing me,"
    },
    {
      "ref": "[R341]",
      "area": "content",
      "claim": "A user states that Roblox supports child predators, implying the platform fails to protect children from inappropriate interactions.",
      "stance": "risk",
      "quote": "Genuinely the most money-hungry game I have ever seen\nThis game supports child predators. That’s all I need to say."
    },
    {
      "ref": "[R333]",
      "area": "content",
      "claim": "A user describes encountering inappropriate behavior in a Brookhaven roleplay scenario, including a child being placed in a bed by another player, which raised safety concerns for a parent.",
      "stance": "risk",
      "quote": "Roblox es fantástico y es el mejor juego ademas deberían de sacar mas juegos como Roblox pero… mi hermana estaba jugando Brookhaven y saluda a un niño y derrepente la carga y bueno El Niño pone su casa y yo viendo a mi hermana y luego El Niño la mete asu casa y la pone en una cama Y mi mamá se dio cuenta y descargo Roblox …😔👊 y yo digo que Roblox banee a esas personas que hacen eso te lo suplico Roblox y para que no hayan problemas confío en ustedes😊"
    },
    {
      "ref": "[R340]",
      "area": "content",
      "claim": "A user claims that Roblox allows kidnapping and murder of players, suggesting the platform enables harmful roleplay scenarios that could normalize violence against children.",
      "stance": "risk",
      "quote": "The worst game you can die because of the game\nDon’t get this game playing this game could kill you people kidnap kids and kill . Why because there are bad people in the world I don’t know why they are bad people. Fix the problem who ever made the game you are killing people maybe you are the bad person"
    },
    {
      "ref": "[R337]",
      "area": "money",
      "claim": "A user reports being charged for an item they previously purchased, with Roblox removing it without refund, constituting a pay-to-win or subscription trap.",
      "stance": "risk",
      "quote": "Roblox did me wrong\nThey want me to pay for something I already paid for and they won’t allow me to update my stuff without paying so now I can’t play my game"
    },
    {
      "ref": "[R345]",
      "area": "money",
      "claim": "A user states their purchased Robux balance was reduced unexpectedly, indicating possible loss of purchased virtual currency without explanation or refund.",
      "stance": "risk",
      "quote": "I got a bone to pick with you Roblox\nI had 1000 Robux exactly 1K and the next day it’s at 700 LIKE WHAT THE HECK why did my Robux go down??   Im ticked off."
    },
    {
      "ref": "[R338]",
      "area": "money",
      "claim": "A user reports being permanently banned from voice chat after using the word 'bench', claiming the moderation was unjust and inconsistent.",
      "stance": "risk",
      "quote": "They Vcb and banned me for no reason,all I said was the word bench an they took my voice chat and banned my account.They be listening to hard and it’s unprofessional, they hear what they wanna hear and that’s not how it’s supposed to work"
    },
    {
      "ref": "[R372]",
      "area": "developer_record",
      "claim": "A user alleges Roblox uses AI moderation that makes frequent errors, including falsely banning players, indicating poor developer oversight and accountability.",
      "stance": "risk",
      "quote": "Fun, but bad moderation\nMost games are fun, except slop games like steal a brainrot or ai made games, also the moderation isn’t even human, they are ai that make mistakes all the time and falsely ban people, and also most updates aren’t even good, like that face scan update, or the update where they removed classic faces and replaced them with creepy 3d ones"
    },
    {
      "ref": "[R347]",
      "area": "age_gating",
      "claim": "A user reports that age restrictions prevented them from playing a favorite game called 'draw me', despite being old enough to play, indicating the age gate fails in practice.",
      "stance": "risk",
      "quote": "something I don't like about roblox\nI need chat to be back٫ it doesn't feel right when there's no chat and communication :( and also I hate this age this and because of it I cant play a game I love called \"draw me\" :( and almost everything is fine in rob lox other than those reasons..."
    },
    {
      "ref": "[R355]",
      "area": "age_gating",
      "claim": "A user states they have played Roblox since age 4 and continue playing at age 10, suggesting the platform's age restrictions are ineffective for younger users who access it anyway.",
      "stance": "neutral",
      "quote": "I love Roblox a lot\nI’ve been playing Roblox ever since I was four years old and I’m 10 now Roblox has been a good game ever since I started playing"
    },
    {
      "ref": "[R305]",
      "area": "age_gating",
      "claim": "A user explicitly requests removal of the age check, stating it alienates long-term players who have used the platform for years without issue.",
      "stance": "neutral",
      "quote": "It’s good but remove the age check\nI’ve been playing Roblox since 2022 and it’s great!but the new updates are kinda bad.If Roblox could remove the age check I think a lot of people would be happy."
    },
    {
      "ref": "[R315]",
      "area": "developer_record",
      "claim": "A user submits an appeal to reverse a termination, claiming their account was mistakenly flagged for evading moderation due to shared family IP address, indicating potential flaws in enforcement systems.",
      "stance": "neutral",
      "quote": "Unbanned me\n: Say this Dear Roblox Moderation Team,\nI am reaching out to appeal the termination of my Roblox account, (Torilovehers ). For avoiding moderation via making an alternative account. I believe this moderation must be a mistake.\nMy siblings and I all play Roblox and share the same IP address. My brother has had his account terminated in the past, which may have caused confusion and led to my account being falsely flagged for evading moderation. However, I want to clarify that I have not created or used any alternate accounts to bypass moderation actions.\nI kindly request a thorough review of my case.\nThank you for your time and consideration. I appreciate your assistance in resolving this matter.\nBest regards, (Torilovehers )."
    },
    {
      "ref": "[R376]",
      "area": "content",
      "claim": "A user states that the removal of classic chat and forced age verification has fundamentally changed Roblox in a negative way, making it feel like a different platform.",
      "stance": "neutral",
      "quote": "Chat update sucks\nBring back old chat Roblox is not the same and remove age verification I hate Roblox now"
    },
    {
      "ref": "[R377]",
      "area": "content",
      "claim": "A user describes the platform's decline in quality, stating updates have made it 'downfall' and that it was better in its previous form, indicating dissatisfaction with recent changes.",
      "stance": "neutral",
      "quote": "Down fall\nHorrible i cant even play adopt me with my sibling because of age restriction. I hate this game it was good but its downfall impacted the game violently. I think this game should go back to how it was bring classic roblox not whatever this is."
    },
    {
      "ref": "[R380]",
      "area": "developer_record",
      "claim": "A user expresses hope that Roblox will add free Christmas items, reflecting expectations for the platform to provide free content despite monetization practices.",
      "stance": "neutral",
      "quote": "From Harmony to Roblox\nVery good Games and can we get free stuff for Christmas please?"
    }
  ]
}
